INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'Mathematics', 'Unit 3', 'Molarum Grade 10 — Mathematics Unit 3: Exponential and Logarithmic Functions', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 3: Exponential and Logarithmic Functions.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('b48ac2a2-7bad-44b6-8d40-f402b7c4ce48'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'In the expression 3^4, which identifies the base and the exponent as defined in the excerpt?', 'Base 3, exponent 4', 'Definition 3.1 states that in a^n the symbol a is the base and n is the exponent, so in 3^4 the base is 3 and the exponent is 4.', 0),('e5be4ccf-ee86-4673-8da9-d80a751bdfb7'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What is the value of (−3)^2 as evaluated in the excerpt examples?', '9', 'Example 1 shows (−3)^2 = (−3)×(−3) = 9, because the negative base squared gives a positive product.', 1),('5acded90-43dd-4f92-8147-529a92f05a18'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'According to Law 1 in the excerpt, a^m × a^n equals which expression?', 'a^(m+n)', 'Law 1 states a^m × a^n = a^(m+n), i.e. when multiplying same base powers, add the exponents.', 2),('edb69fb4-58fa-4568-82e2-5fd3cf049311'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'Which formula matches Law 2 as given in the excerpt for division of powers with same base (a ≠ 0)?', 'a^m / a^n = a^(m−n)', 'Law 2 in the excerpt gives a^m / a^n = a^(m−n) for a ≠ 0, derived by canceling common factors of a.', 3),('91ebb4c9-8d58-44c5-843c-af26527cf438'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What is a^0 for a ≠ 0 according to the excerpt?', '1', 'The excerpt defines a^0 = 1 for a ≠ 0 so that the laws of exponents remain valid when exponents are zero.', 4),('3071532d-ac4d-420c-8d2c-3c46b5b1e0b0'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'Which law states the expansion of (ab)^n as given in the excerpt?', '(ab)^n = a^n b^n', 'Law 4 in the excerpt shows (ab)^n = a^n b^n by distributing n multiplicative factors of ab into n factors of a and n factors of b.', 5),('d8315a37-9fed-4170-8c88-a62665d48e10'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'According to Definition 3.2, a^(−n) equals which of the following (for a ≠ 0)?', '1 / a^n', 'Definition 3.2 states a^(−n) = 1 / a^n for a ≠ 0, extending the exponent laws to negative integers.', 6),('78f158f1-5c78-424f-86ca-f15e90f903e7'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'Which expression matches the Change of Base theorem given in the excerpt?', 'log_a M = (log_b M) / (log_b a)', 'Theorem 3.4 in the excerpt shows log_a M = log_b M divided by log_b a, obtained by taking logs to base b on a^p = M.', 7),('9e0e35d3-3dac-4230-838f-65e268092061'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'The product law for logarithms in Theorem 3.1 states log_a(MN) equals which of these?', 'log_a M + log_a N', 'Theorem 3.1 proves log_a(MN) = log_a M + log_a N by converting log statements to exponentials and using a^p a^q = a^{p+q}.', 8),('cc4909e4-fa7c-4b52-88b3-27d10a4d0c55'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'For any valid base a (a>0, a≠1), what is log_a a according to the excerpt?', '1', 'Property 2 of the logarithm section states log_a a = 1 because a^1 = a.', 9),('d1d3f05d-1fae-4699-8987-68cd5f80ab39'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What is the y-intercept of the exponential function f(x)=a^x as stated in the excerpt?', '(0, 1)', 'The characteristics list shows the y-intercept of f(x)=a^x is (0,1) because a^0 = 1 for a>0.', 10),('6c93ca47-3e7e-4991-8695-32ff2cae8ba0'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What is the domain of the exponential function f(x)=a^x (a>0, a≠1) according to the excerpt?', 'All real numbers', 'The excerpt states the domain of f(x)=a^x is the set of all real numbers since x can be any real exponent.', 11),('02001c7f-595e-4288-8efd-1c125f89178e'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What is the range of the logarithmic function f(x)=log_a x for a>0, a≠1 as given in the excerpt?', 'All real numbers', 'The excerpt explains that the range of y=log_a x is the set of all real numbers because its inverse a^x attains all positive values across real exponents.', 12),('6c5a947d-f750-482b-87be-41083bfc6043'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'If y = a^x, which expression for x is the inverse relation as defined in the excerpt?', 'x = log_a y', 'Definition 3.6 and surrounding text define log_a c = b if and only if a^b = c, so the inverse of y=a^x is x=log_a y.', 13),('8182b948-84d6-411b-826b-972ac15f0dad'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What approximate value of the constant e is given in the excerpt (to five decimal places)?', '2.71828', 'The excerpt tabulates values approaching e and states the approximate value to five decimal places is e ≅ 2.71828.', 14),('5b03ac6e-7a6d-4391-8ab1-eeb91417a416'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'How is the common (base 10) logarithm log_10 M usually denoted in the excerpt?', 'log M', 'Definition 3.7 explains that log_10 M is usually written simply as log M, omitting the base 10.', 15),('49e0d0a3-662a-4a08-81fb-8432fecea392'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'In the decomposition p = m × 10^c with 1≤m<10, what does the excerpt call log m?', 'Mantissa (fractional part)', 'The excerpt states log p = log m + c, where log m is called the mantissa (fractional part) and c the characteristic.', 16),('ecd82eb8-6d87-4c47-8a22-3ade72cf0b20'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'Using the product law, what is log_3 5 + log_3 8 equal to according to the excerpt examples?', 'log_3 40', 'Example 6 applies the product law: log_3 5 + log_3 8 = log_3(5×8) = log_3 40.', 17),('d2475bab-62f1-4478-8eb9-1ef40e132e7a'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'What does Theorem 3.2 state about log_a(M^r) in the excerpt?', 'log_a(M^r) = r log_a M', 'Theorem 3.2 proves log_a(M^r) = r log_a M by converting M to a^p and using exponent rules, thus bringing the exponent down as a multiplier.', 18),('ff2dabdc-6d38-4e0c-826e-8917c49fd6bf'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'multiple_choice', 'Which horizontal line is listed in the excerpt as the horizontal asymptote for y = a^x?', 'y = 0', 'The excerpt states the x-axis (y=0) is a horizontal asymptote of the exponential function y = a^x since values approach zero as x → −∞ (for a>1).', 19),('145c65a5-e9b9-4ae9-87e3-598eb9be27d7'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'true_false', 'Property in the excerpt: For any a>0, a≠1, log_a 1 = 0.', 'True', 'The excerpt lists property 1 of logarithms: log_a 1 = 0 because a^0 = 1.', 20),('93fda87b-c8ec-4e3e-8a4a-919b61fc42c1'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'true_false', 'The excerpt defines a^0 as undefined for all a ≠ 0.', 'False', 'The excerpt defines a^0 = 1 for a ≠ 0 so that exponent laws remain valid; only 0^0 is left undefined.', 21),('17a0b992-dab8-4c5e-85ba-23c8453e94a5'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'true_false', 'According to the excerpt, the graph of y = a^x has the x-axis as a horizontal asymptote.', 'True', 'The characteristics in the excerpt state the x-axis (y=0) is a horizontal asymptote for exponential functions y=a^x.', 22),('bd15d4c8-4015-48f7-814d-065786db8403'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'true_false', 'The excerpt warns that log_a(MN) = (log_a M)(log_a N).', 'False', 'The excerpt explicitly warns that log_a(MN) ≠ (log_a M)(log_a N); instead log_a(MN) = log_a M + log_a N.', 23),('e62deaa0-b0f8-44d9-81e0-218cbac0f879'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'State the definition of the logarithm log_a c = b as given in the excerpt.', 'log_a c = b if and only if a^b = c.', 'Definition 3.6 in the excerpt states log_a c = b iff a^b = c, so a logarithm is the exponent that gives c when a is raised to it.', 24),('795f4bff-46e5-4381-8862-8ea3c7eeabfc'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'Write the compound interest formula for interest compounded n times per year as given in the excerpt.', 'A(t) = P (1 + r/n)^{n t}.', 'Theorem 3.5 gives A(t)=P(1 + r/n)^{nt} where P is principal, r annual rate, n compounding per year and t years.', 25),('f1f5d1b5-4b93-4c44-87ca-c1abd9253831'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'Write the formula for the amount after t years if interest is compounded continuously (as given in the excerpt).', 'A(t) = P e^{r t}.', 'The excerpt explains continuous compounding leads to A = P e^{r t}, where e is the base of natural logarithms and r is annual rate.', 26),('3f331704-e507-46a1-86f5-d1ea6c7220f1'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'What is the domain of f(x)=log_a x as stated in the excerpt?', 'The set of positive real numbers (0, ∞).', 'The excerpt states the domain of y=log_a x is the set of positive real numbers because logs are defined only for x>0.', 27),('ae0d66f3-583d-47a8-8699-511797e25461'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'State the definition of a^{m/n} for natural m,n and positive a as given in the excerpt.', 'a^{m/n} = (a^{1/n})^m, i.e. the n-th root of a raised to the mth power.', 'Definition 3.4 defines a^{m/n} as (a^{1/n})^m, meaning take the n-th root of a and then raise it to the mth power.', 28),('4b300abe-c8e1-4252-88c1-fd75faf41659'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'State Theorem 3.1 (logarithms of products) in one sentence as in the excerpt.', 'For positive M,N and a>0,a≠1: log_a(MN) = log_a M + log_a N.', 'Theorem 3.1 in the excerpt states the log of a product equals the sum of the logs of the factors, derived from exponent laws a^p a^q = a^{p+q}.', 29),('385f8b8d-a959-4d49-8e84-359f12da8cf2'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'Briefly explain the graphical relation between y=a^x and y=log_a x from the excerpt.', 'They are inverse functions and their graphs are reflections of each other across the line y=x, so domain and range swap.', 'The excerpt explains y=a^x and y=log_a x are inverses; graphically log_a x is the reflection of a^x across y=x, exchanging domain and range.', 30),('d2b83c04-2d22-4e5f-8601-7ba7b2f62e56'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'What are the mantissa and characteristic of a common logarithm as described in the excerpt?', 'Mantissa is the fractional part log m and characteristic is the integer c when p=m×10^c so log p=log m + c.', 'The excerpt defines for p=m×10^c (1≤m<10) that log p = log m + c, calling log m the mantissa (fraction) and c the characteristic (integer).', 31),('704a5840-79e6-4c20-8a5c-b78ceebef043'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'Evaluate e^2 to five decimal places as done in the excerpt examples.', '7.38906', 'Example 1 under natural exponential function uses a calculator and reports e^2 ≅ 7.38906 to five decimal places.', 32),('55f55680-1369-40b0-832a-aeffdc69adf3'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'Using the example method in the excerpt, solve 2^x = 20 and give x to five decimal places (the excerpt''s worked result).', '4.32226', 'Example 3 solves 2^x = 20 by taking logs and dividing by log 2; the excerpt gives x ≈ 4.32226 using log2 ≈ 0.3010.', 33),('b84acdd0-7850-4b8b-81c8-85900f596f09'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'From the compound interest example in the excerpt, what is the amount after 5 years for P = 20,000, r = 0.07 compounded annually (n=1) reported in the text?', '28051.03', 'Example 1(a) computes A(5)=20000(1.07)^5 and reports the result ≅ 28051.03 using a calculator as shown in the excerpt.', 34),('d4b1d524-2b01-42be-8bfe-1987f22d4888'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'In the pH example the excerpt gives [H+] = 4.53 × 10^−8 M; what pH value does the excerpt compute?', '7.344', 'The pH example computes pH = −log(4.53×10^−8) = −[log 4.53 − 8] = 7.344 as shown in the text using the log table value log(4.53)=0.6561.', 35),('6dc1b351-af94-4c3a-8dfd-ce0487978f51'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'Using the continuous compounding example in the excerpt, compute A(5) for P=100 and r=0.07 and give the value reported there.', '141.91', 'The excerpt uses A(5)=100 e^{0.07×5}=100 e^{0.35} and reports the calculator value ≅ 141.91 for continuous compounding.', 36),('c16902a6-49e1-4a39-88fa-2583654a54d8'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'In the population growth example the excerpt finds the doubling time for k = 0.023; what value of t (years) does the excerpt give?', '30.14', 'The excerpt solves 2 = e^{0.023 t} by taking ln and gives t = ln 2 / 0.023 ≅ 0.69315/0.023 ≅ 30.14 years as reported.', 37),('fe71df4c-4ddd-4dbb-8d71-37cbf823e1b7'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'What value does the excerpt give for antilog(0.8175) in its antilogarithm example?', '6.569', 'The antilog example in the excerpt finds antilog(0.8175)=6.561 + 0.008 = 6.569 using the antilogarithm table steps shown.', 38),('c05e13e9-ef3c-49c1-892e-aa8f9fd5cb4c'::uuid, 'cbcad6e0-f8de-4e46-8bb2-a5edc8a32d3f'::uuid, 'fill_blank', 'In the excerpt''s example approximating √254, what numerical value for √254 is given after using logarithms and antilogs?', '15.93', 'Example 2 computes log M = 1.2024 and reports antilog(1.2024)=15.93, so √254 ≅ 15.93 as shown in the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDE